import { computeProgressSummary,deriveAdherenceAlerts } from '../engagement/index.js';
function arr(value){return Array.isArray(value)?value:[];}
function first(record,...keys){for(const key of keys){const value=record?.[key];if(value!==undefined&&value!==null&&value!=='')return value;}return null;}
function clientIdOf(record){return first(record,'clientId','client_id','clienteId','cliente_id');}
function dateOf(record){return first(record,'completedAt','completed_at','endedAt','ended_at','updatedAt','updated_at','createdAt','created_at');}
function safeDate(value){const date=value?new Date(value):null;return date&&!Number.isNaN(date.getTime())?date:null;}
function unwrap(record){return record?.body&&typeof record.body==='object'?{...record,...record.body}:record;}
function setRows(execution){const source=unwrap(execution)||{};return [source.results,source.setResults,source.set_results,source.progressSnapshot?.results,source.progress_snapshot?.results].find(Array.isArray)||[];}
function exerciseId(row){return first(row,'exerciseId','exercise_id','idEjercicio','exercise');}
function load(row){const value=Number(first(row,'loadKg','load_kg','load','weightKg','weight_kg'));return Number.isFinite(value)&&value>=0?value:null;}
function latestExecutions(state,clientId,limit=6){return arr(state?.collections?.sessionExecutions).filter((item)=>clientIdOf(item)===clientId).map(unwrap).sort((a,b)=>(safeDate(dateOf(b))?.getTime()||0)-(safeDate(dateOf(a))?.getTime()||0)).slice(0,limit);}
function loadHistory(executions){const previousLoads={};const recentExerciseIds=[];for(const execution of executions){for(const row of setRows(execution)){const id=exerciseId(row);if(!id)continue;if(!recentExerciseIds.includes(id))recentExerciseIds.push(id);const value=load(row);if(previousLoads[id]===undefined&&value!==null)previousLoads[id]=value;}}return {previousLoads,recentExerciseIds};}
function deriveDecision(summary,alerts){const checkin=summary?.latestCheckin||{};const pain=Number(checkin.pain);const sleep=Number(checkin.sleep);const energy=Number(checkin.energy);const stress=Number(checkin.stress);const criticalPain=Number.isFinite(pain)&&pain>=7;const limitedRecovery=(Number.isFinite(sleep)&&sleep<=4)||(Number.isFinite(energy)&&energy<=4)||(Number.isFinite(stress)&&stress>=8)||(Number.isFinite(pain)&&pain>=5);const lowAdherence=Number.isFinite(summary?.adherence)&&summary.plannedSessions>=3&&summary.adherence<0.6;const rapidLoad=Number.isFinite(summary?.volumeDelta)&&summary.volumeDelta>15;
  if(criticalPain)return {level:'hold',reason:'pain_review',progressionAllowed:false,setAdjustment:-1,rpeAdjustment:-2,restAdjustment:30,durationFactor:0.75,patternLimit:4,structure:'series'};
  if(limitedRecovery||(rapidLoad&&lowAdherence))return {level:'reduced',reason:limitedRecovery?'recovery_context':'load_and_adherence',progressionAllowed:false,setAdjustment:-1,rpeAdjustment:-1,restAdjustment:15,durationFactor:0.85,patternLimit:5,structure:'series'};
  if(lowAdherence)return {level:'simplified',reason:'adherence_context',progressionAllowed:false,setAdjustment:0,rpeAdjustment:0,restAdjustment:10,durationFactor:0.85,patternLimit:4,structure:'series'};
  const good=Number.isFinite(summary?.adherence)&&summary.adherence>=0.8&&!alerts.some((item)=>['critical','warning'].includes(item.severity));return {level:'normal',reason:good?'stable_progression':'insufficient_or_neutral_data',progressionAllowed:good,setAdjustment:0,rpeAdjustment:0,restAdjustment:0,durationFactor:1,patternLimit:6,structure:null};
}
export function buildAdaptiveSessionContext(state,clientId,{now=new Date()}={}){
  if(!clientId)throw new Error('M26_ADAPTIVE_CLIENT_REQUIRED');const summary=computeProgressSummary(state,clientId,{now,days:28});const alerts=deriveAdherenceAlerts(state,clientId,{now});const executions=latestExecutions(state,clientId);const history=loadHistory(executions);const decision=deriveDecision(summary,alerts);
  return Object.freeze({clientId,generatedAt:new Date(now).toISOString(),summary,alerts:Object.freeze(alerts),decision:Object.freeze(decision),previousLoads:Object.freeze(history.previousLoads),recentExerciseIds:Object.freeze(history.recentExerciseIds),evidence:Object.freeze({adherence:summary?.adherence??null,averageRpe:summary?.averageRpe??null,volumeDelta:summary?.volumeDelta??null,latestCheckin:summary?.latestCheckin??null,dataQuality:summary?.dataQuality||'limitada'})});
}
export function applyAdaptiveContext(input,state,clientId=input?.clientId,{now=new Date()}={}){const adaptiveContext=buildAdaptiveSessionContext(state,clientId,{now});return Object.freeze({...structuredClone(input),clientId,adaptiveContext,previousLoads:{...adaptiveContext.previousLoads,...(input?.previousLoads||{})},recentExerciseIds:[...new Set([...(adaptiveContext.recentExerciseIds||[]),...(input?.recentExerciseIds||[])])]});}
